package org.beckenburg;

import java.io.*;
import java.security.*;
import java.util.*;
import org.beckenburg.LevelDefinition.*;

/** Independent stepped solids, not generated by the candidate map exporter. */
public final class AuthoredStairPhysicsTest {
    private record Box(String name,double x0,double y0,double z0,double x1,double y1,double z1){}
    private static int checks;
    private static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    private static byte[] encode(List<Box> boxes)throws Exception{
        var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);
        out.writeInt(0x48435332);out.writeInt(boxes.size());out.writeInt(boxes.size()*12);
        int[][] faces={{0,2,1},{0,3,2},{4,5,6},{4,6,7},{0,1,5},{0,5,4},{3,7,6},{3,6,2},{0,4,7},{0,7,3},{1,2,6},{1,6,5}};
        for(Box b:boxes){
            var name=b.name().getBytes(java.nio.charset.StandardCharsets.UTF_8);out.writeShort(name.length);out.write(name);out.writeByte(1);out.writeInt(12);
            Vec[] v={new Vec(b.x0,b.y0,b.z0),new Vec(b.x1,b.y0,b.z0),new Vec(b.x1,b.y1,b.z0),new Vec(b.x0,b.y1,b.z0),new Vec(b.x0,b.y0,b.z1),new Vec(b.x1,b.y0,b.z1),new Vec(b.x1,b.y1,b.z1),new Vec(b.x0,b.y1,b.z1)};
            for(int[] f:faces){for(int i:f){out.writeFloat((float)v[i].x());out.writeFloat((float)v[i].y());out.writeFloat((float)v[i].z());}out.writeByte(7);}
        }return bytes.toByteArray();
    }
    private static AuthoredSitePhysics read(List<Box> boxes,Set<String> steps,List<Collider> blockers)throws Exception{
        byte[] data=encode(boxes);String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));
        return AuthoredSitePhysics.read(new ByteArrayInputStream(data),sha,blockers,steps);
    }
    private static void rejected(List<Box> boxes,Set<String> steps,String why)throws Exception{
        try{read(boxes,steps,List.of());throw new AssertionError("Accepted "+why);}catch(IOException expected){checks++;}
    }
    public static void main(String[] args)throws Exception{
        var boxes=new ArrayList<Box>();var steps=new HashSet<String>();
        boxes.add(new Box("bottom landing",-1.2,-.16,-2,1.2,0,0));
        for(int i=0;i<10;i++){String name="explicit tread "+i;steps.add(name);boxes.add(new Box(name,-1.2,-.16,i*.32,1.2,(i+1)*.18,(i+1)*.32));}
        boxes.add(new Box("top landing",-1.2,1.64,3.2,1.2,1.8,5.2));
        var literal=read(boxes,Set.of(),List.of());var map=read(boxes,steps,List.of());
        Vec first=new Vec(0,.18,.16);
        check(!literal.traversable(first,1.8),"unannotated solids retain literal behavior");
        check(map.bodyBlocked(first,1.8,.22),"literal capsule query still reports riser contact");
        check(map.traversable(first,1.8),"explicit ordinary tread is walkable");
        Vec at=new Vec(0,0,-.5);
        for(int i=1;i<=42;i++){
            Vec next=map.resolveMove(at,0,-.5+i*.1,1.8);check(next!=null,"continuous ascent "+i);at=next;
        }
        check(Math.abs(at.y()-1.8)<1e-6,"ascent reaches real top landing");
        for(int i=1;i<=42;i++){
            Vec next=map.resolveMove(at,0,3.7-i*.1,1.8);check(next!=null,"continuous descent "+i);at=next;
        }
        check(at.y()==0,"descent reaches real bottom landing");
        check(!map.traversable(new Vec(1.1,.9,1.44),1.8),"footprint cannot hang off stair edge");
        check(map.resolveMove(first,0,4,1.8)==null,"oversized movement still rejected");
        check(!map.clearSight(new Vec(0,.1,-.5),new Vec(0,.1,1)),"treads retain optical solidity");
        var wall=new ArrayList<>(boxes);wall.add(new Box("ordinary wall",-1.2,-.16,.28,1.2,3,.36));
        check(read(wall,steps,List.of()).resolveMove(first,0,.6,1.8)==null,"stair mode cannot waive wall");
        var lip=new ArrayList<>(boxes);lip.add(new Box("ordinary low obstruction",-1.2,0,-.2,1.2,.18,-.1));
        check(!read(lip,steps,List.of()).traversable(new Vec(0,0,-.3),1.8),"untagged low obstacle is still physical beside steps");
        var roof=new ArrayList<>(boxes);roof.add(new Box("low roof",-1.2,1.8,0,1.2,2,.64));
        check(!read(roof,steps,List.of()).traversable(first,1.8),"stair mode cannot waive roof");
        var tall=new ArrayList<>(boxes);tall.set(2,new Box("explicit tread 1",-1.2,-.16,.32,1.2,.6,.64));
        check(!read(tall,steps,List.of()).traversable(first,1.8),"step above maximum height stays blocked");
        var gap=new ArrayList<>(boxes);gap.remove(5);var gapNames=new HashSet<>(steps);gapNames.remove("explicit tread 4");
        check(read(gap,gapNames,List.of()).resolveMove(new Vec(0,.72,1.12),0,1.76,1.8)==null,"missing tread cannot become fabricated support");
        check(!read(boxes,steps,List.of(new Collider(0,0,.3,1,.05,3,0))).traversable(first,1.8),"movement-only blockers remain authoritative");
        var seam=new ArrayList<>(boxes);seam.set(2,new Box("explicit tread 1",-1.2,-.16,.320006,1.2,.36,.64));
        check(read(seam,steps,List.of()).support(0,.320003,.18,.25)!=null,"bounded float32 seam on authored tread");
        seam.set(2,new Box("explicit tread 1",-1.2,-.16,.3201,1.2,.36,.64));
        check(read(seam,steps,List.of()).support(0,.32005,.18,.25)==null,"world-space seam allowance cannot bridge a real gap");
        rejected(boxes,Set.of("missing"),"unknown stair identity");
        var ambiguous=new ArrayList<>(boxes);ambiguous.add(boxes.get(1));rejected(ambiguous,steps,"duplicate stair identity");
        System.out.println("PASS "+checks+" authored stair ascent/descent and negative controls; legacy reader unchanged");
    }
}
